let db,legacy=false;
export async function openDB(){
 db=await new Promise((resolve,reject)=>{const r=indexedDB.open('blisko-journal',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});db.onversionchange=()=>db.close();
 return new Promise((resolve,reject)=>{const tx=db.transaction('data'),store=tx.objectStore('data'),rows={};const r=store.openCursor();r.onsuccess=()=>{const cursor=r.result;if(cursor){rows[cursor.key]=cursor.value;cursor.continue()}};tx.oncomplete=()=>{if(rows.meta){const data={...rows.meta,days:{}};for(const [key,value]of Object.entries(rows))if(key.startsWith('day:'))data.days[key.slice(4)]=value;resolve(data)}else{legacy=!!rows.journal;resolve(rows.journal)}};tx.onerror=()=>reject(tx.error)})
}
export async function writeDB(snapshot,expected,replace=false){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite'),store=tx.objectStore('data');let conflict=false;const r=store.get(legacy?'journal':'meta');r.onsuccess=()=>{if((r.result?.rev??0)!==expected){conflict=true;tx.abort();return}const {days,...meta}=snapshot;if(replace)store.clear();else if(legacy){for(const [key,value]of Object.entries(r.result.days))store.put(value,'day:'+key);store.delete('journal')}store.put(meta,'meta');for(const [key,value]of Object.entries(days))store.put(value,'day:'+key)};tx.oncomplete=()=>{legacy=false;resolve()};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(Error(conflict?'Dziennik zmienił się w innej karcie. Zrób kopię bieżących zmian, a potem odśwież aplikację.':'Nie udało się zapisać danych. Sprawdź wolne miejsce w telefonie.'))})}
